// The @sap/hana-client driver will automatically
// use this to add OpenTelemetry support when @opentelemetry/api
// is already installed.

var OTel = {};
try {
    // @opentelemetry/api must be installed by the application in order for
    // the client to use it.
    OTel.API = require('@opentelemetry/api');
    OTel.Tracer = OTel.API.trace.getTracer('@sap/hana-client', '2.29.27');
    // Future: ideally use SEMATTRS_ values from OTel.semConv = require('@opentelemetry/semantic-conventions')
    // Currently do not to avoid the problem of what if @opentelemtry/api is installed but not
    // @opentelemetry/semantic-conventions?
} catch (err) {
    // If module was not found, do not do anything
    // console.log("Failed to load @opentelemetry/api: ", err); // for debugging
    if(OTel.Tracer) {
        OTel.Tracer = undefined;
    }
}

function isOpenTelemetryEnabled() {
    if(OTel.Tracer === undefined) {
        return false;
    }
    const envVar = process.env.HDB_NODEJS_SKIP_OPENTELEMETRY;
    if(envVar && envVar != '0' && envVar.toLowerCase() != 'false') {
        return false;
    }
    return true;
}

// sanitizeSQL(sql) scans the given sql string, and returns a sanitized version:
//   String, number and boolean literals are replaced with ?
//   Comments are removed (both -- and /* */ styles)
// The original sql string is returned if it already contains a ? (assume already parameterized)
// Example of numbers handled: 123, -45.67, .89, +0.1, 1.23E4, 5.67e-8, 0x123abc
// The function scans the input SQL from start to end, and handles edge cases
// such as comments inside strings or identifiers, numbers inside identifiers,
// and attempts to disambiguate + and - immediately before numbers.
// Note that strings can escape a quote with two quotes, and double quoted identifiers
// and also escape a double quote with two double quotes.

// values must be in upper case
const _keywordsNextPlusMinusIsPartOfNumber = new Set(['SELECT', 'WHERE', 'AND', 'OR', 'NOT', 'ON', 'BETWEEN', 'CASE', 'WHEN', 'THEN', 'ELSE', 'DEFAULT']);
const _trueFalseKeywords = new Set(['TRUE', 'FALSE']);
const _stringTypePrefixes = new Set(['N', 'X', 'DATE', 'TIME', 'TIMESTAMP']);

// SQLSanitizer class is used to implement the sanitizeSQL function.
class SQLSanitizer {
    constructor(sql) {
        this.sql = sql;
        this.result = ''; // build up the sanitized SQL here. Make as few appends as possible to reduce maximum memory usage
        this.i = 0; // index into sql
        this.iToAppendToResult = 0; // start index into sql we need to appended to result. We only do append to result and reset this when result needs to differ from sql.
        this.lastIdentifier = undefined; // unquoted identifier immediately before current position
        this.lastTokenValueOrIdentifier = false; // true if the last token was a value, identifier or ')' (used to determine if a + or - is part of a number or a binary operator)
    }

    _isWhitespace(char) {
        return(char === ' ' || char === '\t' || char === '\n' || char === '\r');
    }

    _scanQuotedString(quoteChar) {
        // in a quoted string/identifier (with single or double quotes)
        var copyToResult = quoteChar === '"';
        if(!copyToResult) {
            // copy sql before the quote, then append ?
            this.result += this.sql.slice(this.iToAppendToResult, this.i);
            if(this.lastIdentifier !== undefined && this.lastIdentifier.length > 0 &&
               !this._isWhitespace(this.sql[this.i - 1]) &&
               _stringTypePrefixes.has(this.lastIdentifier.toUpperCase())) {
                // (for cases like N'...' which should all be replaced with ?)
                this.result = this.result.slice(0, -this.lastIdentifier.length);
            }
            this.result += '?';
        }
        this.i++;
        const len = this.sql.length;
        while (this.i < len) {
            if (this.sql[this.i] === quoteChar) {
                this.i++;
                if (this.sql[this.i] === quoteChar) {
                    // Escaped quote
                } else {
                    break;
                }
            }
            this.i++;
        }
        if(!copyToResult) {
            // i is now one past the end of the quoted string
            // skip over 'string' we just added to result, and start the next part of sql to append to result.
            this.iToAppendToResult = this.i;
        }
        this.lastIdentifier = undefined;
        this.lastTokenValueOrIdentifier = true;
    }

    _scanIdentifier() {
        // scan identifier with beginning with a letter and containing only letters, digits, underscores, #
        var startOfIdentifier = this.i;
        this.i++;
        const len = this.sql.length;
        while (this.i < len) {
            const curr = this.sql[this.i];
            if(curr >= 'a' && curr <= 'z' || curr >= 'A' && curr <= 'Z' ||
               curr >= '0' && curr <= '9' || curr === '_' || curr === '#') {
                this.i++;
            } else {
                break;
            }
        }
        // i is now one past the end of the quoted identifier
        this.lastIdentifier = this.sql.slice(startOfIdentifier, this.i);
        var lastIdentiferLen = this.lastIdentifier.length;
        if(lastIdentiferLen >= 4 && lastIdentiferLen <= 5 && _trueFalseKeywords.has(this.lastIdentifier.toUpperCase())) {
            // if the value is TRUE or FALSE, sanitize it as ?
            // copy sql before the TRUE/FALSE to result, then append ?
            this.result += this.sql.slice(this.iToAppendToResult, startOfIdentifier) + '?';
            this.iToAppendToResult = this.i;
            this.lastIdentifier = undefined;
        }
        this.lastTokenValueOrIdentifier = true;
    }

    // return true if a + or - should treated as a binary operator and _not_ part of a number
    _shouldPlusMinusBeOperator() {
        if(this.lastTokenValueOrIdentifier) {
            if(this.lastIdentifier !== undefined && this.lastIdentifier.length > 0 &&
               _keywordsNextPlusMinusIsPartOfNumber.has(this.lastIdentifier.toUpperCase())) {
                // The last identifier is a keyword that indicates the next + or -
                // should be treated as part of a number
                // (for example "SELECT -1 ... WHERE +2 > col2" should be sanitized as "SELECT ? ... WHERE ? > col2")
                return false;
            }
            // Last token was a ')', string, number, quoted identifier, or non-quoted identifier,
            // that wasn't a keyword we care about, so treat + or - as a binary operator
            // (for example "SELECT (col1-1-5)+2" should be sanitized as "SELECT (col1-?-?)+?")
            return true
        }
        // Assume last token was a binary operator, ',' or '(' so treat + or - as part of a number
        // (for example "WHERE (-2 + -1) < +5" should be sanitized as "WHERE (?-?) < ?")
        return false;
    }

    // return true if it was a valid number
    _scanNumber() {
        if(this.sql[this.i] === '0') {
            // handle a hex literal in the form 0x123abc (which should be replaced with ?)
            const hexMatch = this.sql.slice(this.i).match(/^0[xX][0-9a-fA-F]+/);
            if (hexMatch) {
                // copy sql before the hex literal
                this.result += this.sql.slice(this.iToAppendToResult, this.i) + '?';
                this.i += hexMatch[0].length;
                this.iToAppendToResult = this.i;
                this.lastIdentifier = undefined;
                this.lastTokenValueOrIdentifier = true;
                return true;
            }
        }
        const numberMatch = this.sql.slice(this.i).match(/^([+-]?\d+(\.\d+)?([eE][+-]?\d+)?|-?\.\d+([eE][+-]?\d+)?)/);
        if (numberMatch) {
            // a number literal
            // copy sql before the number literal
            this.result += this.sql.slice(this.iToAppendToResult, this.i) + '?';
            this.i += numberMatch[0].length;
            this.iToAppendToResult = this.i;
            this.lastIdentifier = undefined;
            this.lastTokenValueOrIdentifier = true;
            return true;
        }
        return false;
    }

    sanitize() {
        const len = this.sql.length;
        while (this.i < len) {
            if(this.i > 10000 || this.result.length + this.i - this.iToAppendToResult > 1000) {
                // This is a maximum sql and result size to reduce performance impact
                // of sanitizing very large SQL statements.
                // Note _getSpanNameAndStatus limits result sql to 999.
                return this.result + this.sql.slice(this.iToAppendToResult, this.i) + '…';
            }
            var curr = this.sql[this.i];
            if (this.sql.startsWith('--', this.i)) {
                // in single line comment
                // copy sql before the comment
                this.result += this.sql.slice(this.iToAppendToResult, this.i);
                this.i = this.sql.indexOf('\n', this.i);
                this.iToAppendToResult = this.i; // skip the comment in the next append to result
                if (this.i === -1) break; // End of string
            } else if (this.sql.startsWith('/*', this.i)) {
                // in multi line comment
                // copy sql before the comment
                this.result += this.sql.slice(this.iToAppendToResult, this.i);
                this.i = this.sql.indexOf('*/', this.i + 2);
                if (this.i === -1) {
                    this.iToAppendToResult = -1;
                    break; // End of string
                }
                this.i += 2; // Move past */
                this.iToAppendToResult = this.i; // skip the comment in the next append to result
            } else if (curr === '?') {
                // got a value placeholder
                return this.sql; // Return as is (assume it is already parameterized)
            } else if (curr === "'") {
                // in a single quoted string (replace with ?)
                this._scanQuotedString("'");
            } else if (curr === '"') {
                // In double quoted identifier (keep as is)
                this._scanQuotedString('"');
            } else if(curr >= 'a' && curr <= 'z' || curr >= 'A' && curr <= 'Z') {
                // in an undelimited identifier or keyword, (keep as is), sets this.lastIdentifier
                this._scanIdentifier();
            } else {
                // a number, whitespace, operator or invalid character
                if((curr === '-' || curr === '+')&& this._shouldPlusMinusBeOperator()) {
                    // treat as subtraction or addition below (not part of a number)
                } else if(curr === '-' || curr === '+' || (curr >= '0' && curr <= '9') || curr === '.' ) {
                    // might be a number
                    if(this._scanNumber()) {
                        // is actually a number (replaced with ?)
                        continue;
                    }
                    // else (something like ". " or "- ") - treat like a regular character below
                }

                // white space, operator or invalid character if we get here
                if(!this._isWhitespace(curr)) {
                    // if it's not whitespace, then reset lastIdentifier assuming it's an operator
                    this.lastIdentifier = undefined;
                    if(curr === ')') {
                        // a + or - immediately after this must be part of a number
                        this.lastTokenValueOrIdentifier = true;
                    } else {
                        // assume it is a binary operator, ',' or '(' so that
                        // a + or - immediately after this must be part of a number
                        this.lastTokenValueOrIdentifier = false;
                    }
                }
                this.i++;
            }
        }
        if(this.iToAppendToResult >= 0) {
            // append the remaining part of sql to result
            this.result += this.sql.slice(this.iToAppendToResult);
        }
        return this.result;
    }
}

function sanitizeSQL(sql) {
    var sanitizer = new SQLSanitizer(sql);
    const ret = sanitizer.sanitize();
    sanitizer = undefined; // free memory used by sanitizer as soon as possible
    return ret;
}


function _getSpanNameAndStatus(op, sql, conn) {
    // spanName and attributes attempt to follow:
    // https://github.com/open-telemetry/semantic-conventions/blob/main/docs/database/database-spans.md
    // (above page was updated May 2, 2025 I think to version v1.33.0 to mark most DB attributes as stable)

    // The specs says the span name could be <db.operation.name> <db.collection.name>
    // but instead follow CAP and postgresql which roughly use "<operation> - <sql>"
    var spanName = op;
    if(sql) {
        spanName = op + " - " + sql;
        if(spanName.length > 80) {
            spanName = spanName.substring(0, 79) + '…'; // based on what CAP used
        }
    }
    // Future: consider using OTel.semConv.SEMATTRS_DB_ values instead of hardcoding attribute names
    // FYI CAP and postgresql use net.peer.name, and net.peer.port instead of server.address and server.port
    var spanOptions = {kind: OTel.API.SpanKind.CLIENT,
                        attributes: {'db.system.name' : 'sap.hana',
                                     'db.operation.name': op, // the method name, which is roughly the operation being executed
                                     'server.address': conn._destinationInfo.host,}};
    if(conn._destinationInfo.port) {
        try {
            spanOptions.attributes['server.port'] = Number(conn._destinationInfo.port);
        } catch (err) {
            // ignore conversion error
        }
    }
    if(typeof(sql) === 'string') {
        // Follow Dynatrace which limits SQL to 1000 characters
        var sql_text = sql.length > 1000 ? sql.substring(0, 999) + '…' : sql;
        spanOptions.attributes['db.query.text'] = sql_text;
    }
    if(conn._destinationInfo.tenant) {
        spanOptions.attributes['db.namespace'] = conn._destinationInfo.tenant;
    }
    return {spanName: spanName, spanOptions: spanOptions};
}

function _setSpanStatus(span, err) {
    if(err) {
        span.setStatus(Object.assign({code: OTel.API.SpanStatusCode.ERROR }, err.message ? { message: err.message } : undefined));
        if(err.code) {
            // https://opentelemetry.io/docs/specs/semconv/attributes-registry/db/ says this value should be a string
            span.setAttribute('db.response.status_code', err.code.toString());
        }
    } else {
        span.setStatus({code: OTel.API.SpanStatusCode.OK});
    }
}

function _openTelemetryResultCallback(span, activeCtx, cb) {
    return function (err, ...args) {
        _setSpanStatus(span, err);
        const results = args[0];
        if(results !== undefined) {
            span.setAttribute('db.response.returned_rows', (results && results.length) || results);
        }
        span.end();
        if(cb) {
            // propagate the active context for async calls
            // (otherwise spans started within cb will not know the parent span)
            return OTel.API.context.with(activeCtx, function() {
                return cb(err, ...args);
            });
        }
    };
}

function _openTelemetryResultSetCallback(span, activeCtx, cb) {
    return function (err, ...args) {
        const resultSet = args[0];
        _setSpanStatus(span, err);
        if(resultSet) {
            const rowCount = resultSet.getRowCount();
            // A negative rowCount means the number of rows is unknown.
            // This happens if the client hasn't received the last fetch chunk yet (with default server configuration,
            // this happens if the result set is larger than 32 rows)
            if(rowCount >= 0) {
                span.setAttribute('db.response.returned_rows', rowCount);
            }
            // modify resultSet for OpenTelemetry after a successful executeQuery
            // async methods that do not trace to OpenTelemetry
            _setPropagateContextWrapper(resultSet, resultSet.close, "close");
            _setPropagateContextWrapper(resultSet, resultSet.getData, "getData");
            _setPropagateContextWrapper(resultSet, resultSet.getValue, "getValue");
            _setPropagateContextWrapper(resultSet, resultSet.getValues, "getValues");
            _setPropagateContextWrapper(resultSet, resultSet.next, "next");
            _setPropagateContextWrapper(resultSet, resultSet.nextResult, "nextResult");
        }
        span.end();
        if(cb) {
            // propagate the active context for async calls
            // (otherwise spans started within cb will not know the parent span)
            return OTel.API.context.with(activeCtx, function() {
                return cb(err, ...args);
            });
        }
    };
}

// Wrapper for thisArg.origFn that we do NOT want to create a span for (eg stmt.getData)
// but we still want to propagate the active context on an async call.
// The method's callback first parameter must the error object.
function _propagateContextWrapperFn(thisArg, origFn, argsBeforeCallback=0) {
    // args can end with a callback
    return function (...args) {
        var cb;
        if (args.length > argsBeforeCallback && typeof args[args.length - 1] === 'function') {
            cb = args[args.length - 1];
        }
        if(cb) {
            const activeCtx = OTel.API.context.active();
            origFn.call(thisArg, ...args.slice(0, args.length - 1), function (...cbArgs) {
                // propagate the active context for async calls
                // (otherwise spans started within cb will not know the parent span)
                OTel.API.context.with(activeCtx, function() {
                    cb(...cbArgs);
                });
            });
        } else {
            // sync method call
            return origFn.call(thisArg, ...args);
        }
    }
}

// thisArg is the class, origFn is the method, fnName is a string (name of method)
function _setPropagateContextWrapper(thisArg, origFn, fnName, argsBeforeCallback=0) {
    Object.defineProperty(thisArg, fnName, {value: _propagateContextWrapperFn(thisArg, origFn, argsBeforeCallback)});
}

// Wrapper for thisArg.origFn that is not a prepare or execute* method (eg conn.commit)
// to create a span for the operation.
// The method's callback first parameter must the error object.
function _generalWrapperFn(thisArg, origFn, op, conn) {
    // args can end with a callback
    return function (...args) {
        var cb;
        var activeCtx;
        if (args.length > 0 && typeof args[args.length - 1] === 'function') {
            cb = args[args.length - 1];
            activeCtx = OTel.API.context.active();
        }
        const {spanName, spanOptions} = _getSpanNameAndStatus(op, undefined, conn);
        return OTel.Tracer.startActiveSpan(spanName, spanOptions, function(span) {
            if(cb) {
                // async method call
                return origFn.call(thisArg, ...args.slice(0, args.length - 1), function (...cbArgs) {
                    // if cbArgs is empty, cbArbs[0] is undefined, so this is safe
                    _setSpanStatus(span, cbArgs[0]);
                    span.end();
                    // propagate the active context for async calls
                    // (otherwise spans started within cb will not know the parent span)
                    OTel.API.context.with(activeCtx, function() {
                        cb(...cbArgs);
                    });
                });
            } else {
                // sync method call
                var result;
                try {
                    result = origFn.call(thisArg, ...args);
                    _setSpanStatus(span);
                    span.end();
                } catch (err) {
                    _setSpanStatus(span, err);
                    span.end();
                    throw err;
                }
                return result;
            }
        });
    }
}

// wrapper for execute, executeBatch, and executeQuery
function _executeWrapperFn(thisArg, conn, execFn, op, resultCB, sql) {
    // connection exec args = [sql, options, callback] --> options and callback is optional
    // stmt exec args = [options, callback] --> options and callback is optional
    return function (...args) {
        if(thisArg === conn && args.length > 0) {
            sql = args[0];
        }
        if(typeof(sql) === 'string') {
            if(conn._sanitize) {
                sql = sanitizeSQL(sql);
            }
        } else {
            sql = ''; // execute will fail, but need sql for when the error is traced
        }
        var cb;
        var activeCtx;
        if (args.length > 0 && typeof args[args.length - 1] === 'function') {
            cb = args[args.length - 1];
            activeCtx = OTel.API.context.active();
        }
        const {spanName, spanOptions} = _getSpanNameAndStatus(op, sql, conn);
        return OTel.Tracer.startActiveSpan(spanName, spanOptions, function(span) {
            if(cb) {
                // async execute
                return execFn.call(thisArg, ...args.slice(0, args.length - 1), resultCB(span, activeCtx, cb));
            } else {
                // sync execute
                var result;
                try {
                    result = execFn.call(thisArg, ...args);
                    resultCB(span)(undefined, result);
                } catch (err) {
                    _setSpanStatus(span, err);
                    span.end();
                    throw err;
                }
                return result;
            }
        });
    }
}

// modify stmt for OpenTelemetry after a successful prepare
function _modifyStmt(stmt, conn, sql) {
    const originalExecFn = stmt.exec;
    stmt.exec = _executeWrapperFn(stmt, conn, originalExecFn, "execute", _openTelemetryResultCallback, sql);
    stmt.execute = stmt.exec;

    const originalExecBatchFn = stmt.execBatch;
    stmt.execBatch = _executeWrapperFn(stmt, conn, originalExecBatchFn, "executeBatch", _openTelemetryResultCallback, sql);
    stmt.executeBatch = stmt.execBatch;

    const originalExecQueryFn = stmt.execQuery;
    stmt.execQuery = _executeWrapperFn(stmt, conn, originalExecQueryFn, "executeQuery", _openTelemetryResultSetCallback, sql);
    stmt.executeQuery = stmt.execQuery;

    // async methods that do not trace to OpenTelemetry
    _setPropagateContextWrapper(stmt, stmt.drop, "drop");
    _setPropagateContextWrapper(stmt, stmt.getData, "getData");
    _setPropagateContextWrapper(stmt, stmt.getParameterValue, "getParameterValue");
    _setPropagateContextWrapper(stmt, stmt.sendParameterData, "sendParameterData");
}

function _prepareWrapperFn(conn, prepareFn) {
    // args = [sql, options, callback] --> options is optional
    return function (...args) {
        var cb;
        var activeCtx;
        if(args.length > 0 && typeof args[args.length - 1] === 'function') {
            cb = args[args.length - 1];
            activeCtx = OTel.API.context.active();
        }
        var sql = args[0];
        if(typeof(sql) === 'string') {
            if(conn._sanitize) {
                sql = sanitizeSQL(sql);
            }
        } else {
            sql = ''; // prepare will fail, but need sql for when the error is traced
        }
        const {spanName, spanOptions} = _getSpanNameAndStatus("prepare", sql, conn);
        return OTel.Tracer.startActiveSpan(spanName, spanOptions, function(span) {
            if(cb) {
                // async prepare
                prepareFn.call(conn, ...args.slice(0, args.length - 1), function prepare_handler(err, stmt) {
                    _setSpanStatus(span, err);
                    span.end();
                    // propagate the active context for async calls
                    // (otherwise spans started within cb will not know the parent span)
                    OTel.API.context.with(activeCtx, function() {
                        if (err) {
                            cb(err);
                        } else {
                            _modifyStmt(stmt, conn, sql);
                            cb(err, stmt);
                        }
                    });
                });
            } else {
                // sync prepare
                try {
                    var stmt = prepareFn.call(conn, ...args);
                    _setSpanStatus(span);
                    span.end();
                    _modifyStmt(stmt, conn, sql);
                    return stmt;
                } catch (err) {
                    _setSpanStatus(span, err);
                    span.end();
                    throw err;
                }
            }
        });
    }
}

// destinationInfo is an object with host, port and optionally tenant keys
// sanitize is a boolean
function openTelemetryConnection(conn, destinationInfo, sanitize) {
    if(OTel.Tracer === undefined) {
        return conn;
    }
    conn._sanitize = sanitize;
    if(conn._destinationInfo) {
        // openTelemetryConnection has already been called on conn, use new destinationInfo
        // in case it changed, but don't wrap conn again
        conn._destinationInfo = destinationInfo;
        return conn;
    }
    conn._destinationInfo = destinationInfo;
    // hana-client does not like decorating.
    // because of that, we need to override the fn and pass the original fn for execution
    const originalExecFn = conn.exec;
    conn.exec = _executeWrapperFn(conn, conn, originalExecFn, "execute", _openTelemetryResultCallback);
    conn.execute = conn.exec;
    const originalPrepareFn = conn.prepare;
    // Must use defineProperty and not just conn.<method> = ... for N-API methods.
    // (The execute methods are set to non-N-API JavaScript methods by
    // index.js dynamicallyAddConnExecMethod)
    Object.defineProperty(conn, 'prepare', {value: _prepareWrapperFn(conn, originalPrepareFn)});

    const originalCommitFn = conn.commit;
    Object.defineProperty(conn, 'commit', {value: _generalWrapperFn(conn, originalCommitFn, "commit", conn)});
    const originalRollbackFn = conn.rollback;
    Object.defineProperty(conn, 'rollback', {value: _generalWrapperFn(conn, originalRollbackFn, "rollback", conn)});

    // async methods that do not trace to OpenTelemetry
    _setPropagateContextWrapper(conn, conn.abort, "abort");
    _setPropagateContextWrapper(conn, conn.cancel, "cancel");
    _setPropagateContextWrapper(conn, conn.clean, "clean");
    _setPropagateContextWrapper(conn, conn.clearPool, "clearPool");
    _setPropagateContextWrapper(conn, conn.close, "close");
    _setPropagateContextWrapper(conn, conn.disconnect, "disconnect");
    _setPropagateContextWrapper(conn, conn.end, "end");
    _setPropagateContextWrapper(conn, conn.isValid, "isValid");
    _setPropagateContextWrapper(conn, conn.onTrace, "onTrace", 2); // need to specify 2 because the 2nd parameter is also a function
    _setPropagateContextWrapper(conn, conn.setPassport, "setPassport", 3); // need to specify 3 because the 3rd parameter is also a function
    _setPropagateContextWrapper(conn, conn.switchUser, "switchUser");

    return conn;
}

// export sanitizeSQL for testing
module.exports = { openTelemetryConnection, isOpenTelemetryEnabled, sanitizeSQL };
